-- Ids are UUIDv7 generated by the application in Go (uuid.New), never by the
-- database. create_tasks (already applied wherever this example ran) gave the
-- column a uuidv7() default, a function that only exists on PostgreSQL 18 and would hand a
-- row inserted without an id a value the application did not choose. A released
-- migration is never edited, so this one drops the default.
ALTER TABLE tasks ALTER COLUMN id DROP DEFAULT;
